<template>
  <div class="container">
    <div class="row">
      <div class="col-xs-12">
        <div class="block block-login" style="text-align:center; min-height:0px;">
          <div id="NoticeId">
            <h3>{{title}}</h3>
            {{message}}
          </div>
          <br />
          <button id="ContinueButton" class="btn btn-primary profileBtn" @click="openPage('/')">Try again</button>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
export default {
  name: "NoTice",
  data() {
    return {
      title: null,
      message: null
    }
  },
  async mounted() {
    if(localStorage.getItem("isFatalError")) {
      // this.title = "ACCESS DENIED";
      // this.message = localStorage.getItem("errorMessage");

      localStorage.removeItem("isFatalError");
      localStorage.removeItem("errorMessage");

      await this.$store.commit('resetStore', this.$store.state);
    } else {
      this.title = "SERVER IS DOWN";
      localStorage.clear();
    }
  },
  methods: {
    openPage(name) {
        this.$router.push("/accounting" + name);
    }
  }
};
</script>