export default class MvvMFinance {
    constructor(dataRow) {
        if(dataRow) {
            this.id = dataRow.id;
            this.type = dataRow.type;
            this.name = dataRow.name;
            this.amount = dataRow.amount;
            this.comments = dataRow.comments;
            this.date = dataRow.date;
            this.timeStamp = dataRow.timeStamp;
        } else {
            this.id = 0;
            this.type = null;
            this.name = null;
            this.amount = 0;
            this.comments = null;
            this.date = new Date();
            this.timeStamp = new Date();
        }
    }
}

export function GetMvvMFinance(dataRow) {
    return new MvvMFinance(dataRow);
  }