<template>
    <div class="container">
        <div class="row">
            <h2>{{this.$router.currentRoute.value.name}}</h2>
            <div class="col-xs-12 col-sm-12">   
                <div class="block block-data">
                    <div class="inner">
                        <table class="table" style="border-collapse:collapse;">
                            <thead>
                                <th>
                                    Username
                                </th>
                                <th>
                                    Email
                                </th>
                                <th>
                                    IsAdmin
                                </th>
                            </thead>
                            <tbody>
                                <tr v-for="row in data" :key="row.username">
                                    <td>
                                        {{row.username}}
                                    </td>
                                    <td>
                                        {{row.recoveryEmail}}
                                    </td>
                                    <td>
                                        {{row.isAdmin}}
                                    </td>
                                </tr>
                            </tbody>
                        </table>
                    </div>
                    <br>
                    <label for="Username">Write username of account you want to delete</label>
                    <br />
                    <input id="Username" autocomplete="new-password" class="form-control" maxlength="100" style="display:inline-block; width:90%" v-on:keyup.enter="deleteAccount($event)" v-model="username"/>
                    <span class="tdspaced" style="color: red;" v-if="triedDeleting && !username.trim()">*</span>
                    <br />
                    <button id="DeleteUser" class="btn btn-danger profileBtn" @click="deleteAccount($event)">Delete User and Data</button>
                </div>
            </div>
        </div>
    </div>
</template>

<script>
import CommunicationHelpers from "../../../helpers/CommunicationHelpers.js";

export default {
  name: "AdminIstration",
  data() {
    return {
        data: [],
        username: "",
        interval: null,
        triedDeleting: false
    }
  },
  
  async mounted() {
    this.$store.state.loading = true;

    if(localStorage.token && localStorage.login) {
        this.$store.state.token = localStorage.token;
        this.$store.state.accessToken = this.$store.state.token;
        this.$store.state.userIdentity.user.username = localStorage.login;

        this.$store.state.userIdentity.user = await CommunicationHelpers.apiDataPost("/api/v1/user/GetInfo", this.$store.state);

        if(this.$store.state.userIdentity.user) {
          this.interval = await setInterval(await this.resetToken, 900000);
          localStorage.setItem("tokenSetTime", Date.now());

          this.data = await this.getData();
        }
    } else {
        await this.$store.commit('resetStore', this.$store.state);
    }

    this.$store.state.loading = false;
  },
  methods: {
    focus(id) {
        document.getElementById(id).focus();
    },
    async getData() {
        this.$store.state.loading = true;
        
        let result = await CommunicationHelpers.apiDataPost("/api/v1/admin/GetAllUsers", this.$store.state);

        this.$store.state.loading = false;

        return result;
    },
    async resetToken() {
        this.$store.state.loading = true;

        await CommunicationHelpers.apiDataPost("/api/v1/user/Logout", this.$store.state);

        await this.$store.commit('resetStore', this.$store.state);

        this.$store.state.loading = false;
    },
    async deleteAccount(event) {
        this.triedDeleting = true;

        if(!this.username.trim()) {
            event.preventDefault();
        } else {
            if(confirm("Are you sure you want to delete user and all data?")) {
                this.$store.state.loading = true;

                this.triedDeleting = false;

                this.$store.state.searchString = this.username;
                
                if(CommunicationHelpers.displaySuccessResponse(await CommunicationHelpers.apiDataPost("/api/v1/admin/DeleteAccount", this.$store.state))) {
                    this.username = "";
                }

                this.data = await this.getData();

                this.$store.state.loading = false;
            }
        }
    }
  }
};
</script>