export default class MvvMName {
    constructor(dataRow) {
        if(dataRow) {
            this.id = dataRow.id;
            this.name = dataRow.name;
        } else {
            this.id = 0;
            this.name = null;
        }
    }
}

export function GetMvvMName(dataRow) {
    return new MvvMName(dataRow);
  }